import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BWTY_seE.js";const u=JSON.parse('{"title":"AI 动态 · 2026-10-22","description":"","frontmatter":{"title":"AI 动态 · 2026-10-22","date":"2026-10-22T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-10/ai-news-2026-10-22.md","filePath":"news/2026-10/ai-news-2026-10-22.md","lastUpdated":null}'),s={name:"news/2026-10/ai-news-2026-10-22.md"};function i(o,e,l,c,p,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-10-22" tabindex="-1">AI 动态 · 2026-10-22 <a class="header-anchor" href="#ai-动态-·-2026-10-22" aria-label="Permalink to &quot;AI 动态 · 2026-10-22&quot;">​</a></h1><blockquote><p>截至 2026-10-22。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="deepseek-据报融资-150-亿美元-距美国限制令仅数日" tabindex="-1">DeepSeek 据报融资 150 亿美元，距美国限制令仅数日 <a class="header-anchor" href="#deepseek-据报融资-150-亿美元-距美国限制令仅数日" aria-label="Permalink to &quot;DeepSeek 据报融资 150 亿美元，距美国限制令仅数日&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/4918b126042d.webp" alt="配图"></p><p>TechCrunch 报道，DeepSeek 完成约 150 亿美元融资，成为中国规模最大的融资轮之一；而就在数天前，美国以国家安全为由要求联邦机构移除其技术。融资与监管正面碰撞，说明资本仍在押注中国大模型，但合规与供应链风险同步抬升。对读者：涉及跨境业务或采购的团队，应把模型来源的监管状态纳入供应商风险评估清单。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/22/deepseek-reportedly-raises-15b-days-after-us-restrictions/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai、anthropic、nvidia-游说支出创季度新高" tabindex="-1">OpenAI、Anthropic、Nvidia 游说支出创季度新高 <a class="header-anchor" href="#openai、anthropic、nvidia-游说支出创季度新高" aria-label="Permalink to &quot;OpenAI、Anthropic、Nvidia 游说支出创季度新高&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/f549ac32a33d.jpg" alt="配图"></p><p>联邦披露文件显示，7 至 9 月 OpenAI、Anthropic、Nvidia 均录得各自最高的季度游说支出：Nvidia 220 万美元、Anthropic 210 万美元、OpenAI 150 万美元。绝对金额仍低于微软、谷歌等老牌巨头，但增速表明 AI 公司正加速介入中期选举前的政策议程。对读者：关注 AI 监管动向时，可把游说披露当作政策风向的先行指标。</p><p class="news-entry-source"><a href="https://www.theverge.com/policy/1016585/openai-anthropic-nvidia-lobbying-records" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="meta-拟设新类别股票-为-ai-大规模投入融资" tabindex="-1">Meta 拟设新类别股票，为 AI 大规模投入融资 <a class="header-anchor" href="#meta-拟设新类别股票-为-ai-大规模投入融资" aria-label="Permalink to &quot;Meta 拟设新类别股票，为 AI 大规模投入融资&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/b38b231e20f2.webp" alt="配图"></p><p>TechCrunch 报道，Meta 计划通过新创设的股票类别为其在 AI 模型与服务上的广泛投资提供资金支持。这是继大规模资本开支之后，社交巨头在财务结构上的又一次腾挪，反映 AI 基建投入对现金流的压力正在向股权设计传导。对读者：跟踪 Meta 财报时，留意新股权结构对每股收益与治理结构的稀释影响。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/21/meta-wants-to-pay-for-its-broad-ai-buildout-with-a-newly-created-class-of-stock/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="nirva-融资-3300-万美元-做只监听你的挂坠设备" tabindex="-1">Nirva 融资 3300 万美元，做只监听你的挂坠设备 <a class="header-anchor" href="#nirva-融资-3300-万美元-做只监听你的挂坠设备" aria-label="Permalink to &quot;Nirva 融资 3300 万美元，做只监听你的挂坠设备&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/f24eb3fabbe1.webp" alt="配图"></p><p>Nirva 完成 3300 万美元融资，其 249 美元的随身 AI 挂坠主打「只监听佩戴者本人」，计划年底前发货。在 AI 硬件普遍遇冷的背景下，隐私边界明确的小型设备成为新的差异化切口。对读者：评估此类可穿戴 AI 产品时，重点核查其本地处理比例与数据留存策略，而非只看功能演示。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/22/nirva-raises-33m-for-a-pendant-that-only-listens-to-you/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="uber-向三万余名员工全面部署-chatgpt-work" tabindex="-1">Uber 向三万余名员工全面部署 ChatGPT Work <a class="header-anchor" href="#uber-向三万余名员工全面部署-chatgpt-work" aria-label="Permalink to &quot;Uber 向三万余名员工全面部署 ChatGPT Work&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/54774893a0d4.webp" alt="配图"></p><p>Uber 正在把 ChatGPT Work 推广到超过 3 万名员工，用于资料研究、数据分析、制作演示文稿和完成复杂工作流。这是企业级 AI 助手少见的大规模全员落地案例，也意味着采购决策从试点转向全公司基础设施。对读者：若你正在做内部 AI 工具选型，可参考其按岗位场景而非按部门试点的推广路径。</p><p class="news-entry-source"><a href="https://openai.com/index/uber-chatgpt-work-rollout" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="完整-claude-platform-上线-google-cloud" tabindex="-1">完整 Claude Platform 上线 Google Cloud <a class="header-anchor" href="#完整-claude-platform-上线-google-cloud" aria-label="Permalink to &quot;完整 Claude Platform 上线 Google Cloud&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/ddf0abc2f3f0.webp" alt="配图"></p><p>Anthropic 宣布 Claude Platform 全量登陆 Google Cloud（Anthropic 托管模式），可使用 Google Cloud 的身份认证、计费与承诺额度抵扣。多云可用性降低了对单一云厂商的绑定，也让企业能在既有云合同中消化 Claude 用量。对读者：已有 Google Cloud 承诺额度的团队，可评估把 Claude 调用并入同一账单以简化成本核算。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/claude-models-on-google-cloud-anthropic-managed" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-duet-应用发布-anthropic-押注主动型-agent" tabindex="-1">Claude Duet 应用发布，Anthropic 押注主动型 Agent <a class="header-anchor" href="#claude-duet-应用发布-anthropic-押注主动型-agent" aria-label="Permalink to &quot;Claude Duet 应用发布，Anthropic 押注主动型 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/e5932d2f13e0.webp" alt="配图"></p><p>TechCrunch 报道，Anthropic 推出 Claude Duet，覆盖移动端与桌面端，主打主动执行动作的 Agent 能力，目前以候补名单形式向 Pro 和 Max 用户开放。这是 Anthropic 在消费级 Agent 形态上的正面下注，与同类产品争夺「代理入口」。对读者：可先申请候补做小范围试用，重点观察其在权限边界与误操作回滚上的设计。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/22/claude-duet-app-is-anthropics-bet-on-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="ibm-发布-granite-speech-5-0-2b-多语种转写与翻译" tabindex="-1">IBM 发布 Granite Speech 5.0 2B，多语种转写与翻译 <a class="header-anchor" href="#ibm-发布-granite-speech-5-0-2b-多语种转写与翻译" aria-label="Permalink to &quot;IBM 发布 Granite Speech 5.0 2B，多语种转写与翻译&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-22">2026-10-22</time></p><p>IBM 推出 Apache 2.0 协议的 Granite Speech 5.0 2B 语音识别与翻译模型，在 Open ASR 排行榜以 5.68% 平均英文词错率位列第二，同时更新 Turbo CTC 与 4.1 2B Plus。开源语音栈的精度与许可友好度继续提升。对读者：需要自托管转写能力的团队，可用它替换部分商业 ASR 以控制成本与数据外流。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/22/ibm-granite-speech-5-0-2b-release/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="anthropic-将-agent-skills-标准捐赠给-agentic-ai-基金会" tabindex="-1">Anthropic 将 Agent Skills 标准捐赠给 Agentic AI 基金会 <a class="header-anchor" href="#anthropic-将-agent-skills-标准捐赠给-agentic-ai-基金会" aria-label="Permalink to &quot;Anthropic 将 Agent Skills 标准捐赠给 Agentic AI 基金会&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Anthropic News</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/0115e8c4af7b.webp" alt="配图"></p><p>Anthropic 把 Agent Skills 这一为 AI Agent 提供专门知识与工作流的开放标准捐给 Agentic AI Foundation。自 2025 年 12 月发布以来，包括 ChatGPT、Cursor、GitHub Copilot 和 VS Code 在内的 70 多个 Agent 平台已集成该标准。对读者：标准移交基金会通常意味着治理更中立，长期项目可放心把 Skills 纳入技术栈规划。</p><p class="news-entry-source"><a href="https://www.anthropic.com/news/donating-agent-skills-to-the-agentic-ai-foundation" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="recursive-开源-flint-40b-moe-本地编码模型-激活仅-2-5b" tabindex="-1">Recursive 开源 Flint：40B MoE 本地编码模型，激活仅 2.5B <a class="header-anchor" href="#recursive-开源-flint-40b-moe-本地编码模型-激活仅-2-5b" aria-label="Permalink to &quot;Recursive 开源 Flint：40B MoE 本地编码模型，激活仅 2.5B&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-22">2026-10-22</time></p><p>Recursive 发布 Flint，Apache 2.0 协议的本地编码模型，总参数 40B、激活参数 2.5B，报告 SWE-bench Verified 74.2%，在 M4 Pro MacBook Pro 上可达每秒 125+ token。稀疏 MoE 让本地编码 Agent 在消费级硬件上变得可用。对读者：想在笔记本上跑编码 Agent 的团队，可把 Flint 列入与云端模型对照的候选。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/21/recursive-flint-local-coding-model/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="vercel-开源-durable-harness-让编码-agent-崩溃可续跑" tabindex="-1">Vercel 开源 durable-harness，让编码 Agent 崩溃可续跑 <a class="header-anchor" href="#vercel-开源-durable-harness-让编码-agent-崩溃可续跑" aria-label="Permalink to &quot;Vercel 开源 durable-harness，让编码 Agent 崩溃可续跑&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-22">2026-10-22</time></p><p>Vercel 发布开源包 durable-harness，记录每一次模型与工具调用，使 Pi、OpenCode、Claude Code 和 Codex 的会话在崩溃、超时或重新部署后能够恢复，可运行在 Vercel、Postgres 或本地笔记本上。长任务 Agent 的可靠性短板有了通用解法。对读者：跑长时间编码 Agent 的团队可优先接入，减少重跑带来的 token 浪费。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/21/vercel-durable-harness-crash-proof-coding-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-把-99-99999-仓库副本迁至-azure-为-agent-规模铺路" tabindex="-1">GitHub 把 99.99999% 仓库副本迁至 Azure，为 Agent 规模铺路 <a class="header-anchor" href="#github-把-99-99999-仓库副本迁至-azure-为-agent-规模铺路" aria-label="Permalink to &quot;GitHub 把 99.99999% 仓库副本迁至 Azure，为 Agent 规模铺路&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-10-22">2026-10-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/be7e8cef2443.png" alt="配图"></p><p>GitHub 披露已将 99.99999% 的仓库副本迁移到 Azure，剩余部分将通过按引用仲裁完成，并用对象存储让读取能力独立扩展。底层重构的目标是支撑 Agent 规模下的 Git 访问压力。对读者：重度依赖 GitHub API 的自动化与 Agent 工作流，可关注后续限流与延迟指标变化。</p><p class="news-entry-source"><a href="https://github.blog/engineering/architecture-optimization/the-bridge-to-agent-scale-git-infrastructure/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="cloudflare-联合-oxc-用-rust-重写-typescript-实测约快-2-倍" tabindex="-1">Cloudflare 联合 Oxc 用 Rust 重写 TypeScript，实测约快 2 倍 <a class="header-anchor" href="#cloudflare-联合-oxc-用-rust-重写-typescript-实测约快-2-倍" aria-label="Permalink to &quot;Cloudflare 联合 Oxc 用 Rust 重写 TypeScript，实测约快 2 倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-10-22">2026-10-22</time></p><p>Cloudflare 与 VoidZero 合作把 TypeScript 编译器移植到 Rust，项目 tsrs 孵化于 Oxc 工具链。作者在 1 核 2G 机器上用 199 个文件对比 tsc 7.0.2，报错逐字符一致、速度约 2 倍，但退出码行为不同。对读者：尝鲜前务必核对 CI 中依赖退出码的脚本，避免流水线误判。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7699373348027564082" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',8)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
